  "Try Jessica — a free study app for Egyptian students: Ministry books, an AI tutor, exams and flashcards. Free, offline and no account needed.": "جرّب جيسيكا — تطبيق مذاكرة مجاني لطلاب مصر: كتب الوزارة، مدرّس ذكي، امتحانات وبطاقات. مجاني وأوفلاين وبدون حساب.",
  "The Egyptian Ministry of Education owns the copyright of its textbooks. Jessica does not host, sell or redistribute these files. The Library only points to links published on the Ministry’s own public servers.": "وزارة التربية والتعليم المصرية هي صاحبة حقوق كتبها. جيسيكا مش بتستضيف أو تبيع أو تعيد توزيع الملفات دي. المكتبة بتشير بس لروابط منشورة على سيرفرات الوزارة الرسمية.",

