  "{n} free actions left today.": "فاضل لك {n} استخدام مجاني النهارده.",
  "No key and no trial configured — everything works except AI.": "مفيش مفتاح ولا تجربة مجانية متظبطة — التطبيق شغال بكل حاجة غير الـAI.",
  "Ready — works without internet.": "جاهز — بيشتغل بدون إنترنت.",
