  "Jessica has no account and no server. Your books, key and progress live in this browser. The only network requests are to your AI provider, the Ministry file host, the anonymous usage counter and anonymous crash reports (both can be turned off).": "Jessica مفيش فيها حساب ولا سيرفر. كتبك ومفتاحك وتقدمك على المتصفح ده. الطلبات الوحيدة على الشبكة لمزوّد الذكاء الاصطناعي، وسيرفر ملفات الوزارة، وعداد الاستخدام وبلاغات الأخطاء المجهولة (الاتنين يمكن إيقافهم).",
