  "Disclaimer & terms of use": "إخلاء المسؤولية وشروط الاستخدام",
  "Please read and accept these terms. They keep Jessica free and independent, and make clear that every learner is responsible for how they use the books and the AI.": "اقرأ ووافق على الشروط دي. هي اللي بتخلي Jessica مجانية ومستقلة، وبتوضح إن كل طالب مسؤول عن طريقة استخدامه للكتب والذكاء الاصطناعي.",
