  "Jessica only links to the official files. Use them for your own study and do not re-upload or share them.": "Jessica بتوفر روابط للملفات الرسمية بس. استخدمها لمذاكرتك ومتعيدش رفعها أو تشاركها.",
  "You are responsible for your use": "أنت مسؤول عن استخدامك",
  "You agree to follow the law and your school’s rules when you download or import a book.": "أنت موافق تلتزم بالقانون وبقواعد مدرستك عند تحميل أو استيراد أي كتاب.",
  "Explanations and questions are generated by AI. Always check the original page, especially before exams.": "الشرح والأسئلة بتتولد بالذكاء الاصطناعي. راجع الصفحة الأصلية دايمًا، خصوصًا قبل الامتحانات.",
  "Your data stays on your device": "بياناتك على جهازك",
  "No account and no server. Your key, books and progress live in this browser.": "مفيش حساب ولا سيرفر. مفتاحك وكتبك وتقدمك على المتصفح ده.",
  "Hide the full text": "اخفي النص الكامل",
  "Read the full disclaimer": "اقرأ إخلاء المسؤولية كامل",
  "I have read and accept the disclaimer and terms of use. I understand that I am responsible for how I use official books and for checking AI answers.": "قرأت إخلاء المسؤولية وشروط الاستخدام وموافق عليها. وأفهم إني مسؤول عن طريقة استخدامي لكتب الوزارة وعن مراجعة إجابات الذكاء الاصطناعي.",
  "You need to accept the terms to use Jessica. Nothing is saved or downloaded until you agree.": "لازم توافق على الشروط عشان تستخدم Jessica. مفيش أي حاجة بتتحفظ أو بتتحمل قبل الموافقة.",
  "Accept and continue": "أوافق وأكمل",
  "I do not agree": "مش موافق",
  "Disclaimer": "إخلاء المسؤولية",
  "Disclaimer & copyright": "إخلاء المسؤولية وحقوق النشر",
  "Official textbooks belong to the Ministry of Education. Jessica only links to them; every user is responsible for how they use them.": "كتب الوزارة ملك وزارة التربية والتعليم. Jessica بتوفر روابط ليها بس، وكل مستخدم مسؤول عن طريقة استخدامه.",
  "Ministry books and copyright": "كتب الوزارة وحقوق النشر",
  "The Egyptian Ministry of Education (MOE) owns the copyright of its textbooks. Jessica does not host, sell or redistribute these files. The Library only points to links published on the Ministry’s own public servers, and the PDF is downloaded by the user’s browser.": "حقوق طبع ونشر الكتب ملك وزارة التربية والتعليم. Jessica مش بتستضيف الكتب أو تبيعها أو تعيد نشرها. المكتبة بتوفر روابط منشورة على سيرفرات الوزارة الرسمية، والملف بيتحمّل من متصفح المستخدم.",
  "Use official books for your own personal study only. Do not re-upload or share the files.": "استخدم كتب الوزارة للمذاكرة الشخصية بس. ممنوع إعادة رفع الملفات أو مشاركتها.",
  "You are responsible for complying with the law and with your school’s rules when you download or import a book.": "أنت مسؤول عن الالتزام بالقانون وبقواعد مدرستك عند تحميل أو استيراد أي كتاب.",
  "Jessica is an independent study tool and is not affiliated with or endorsed by the Ministry of Education.": "Jessica أداة مذاكرة مستقلة، ومش تابعة لوزارة التربية والتعليم ولا معتمدة منها.",
  "If you own the rights to a file and want a link removed, contact us and we will remove it promptly.": "لو أنت مالك حقوق ملف وعايز اللينك يتشال، كلّمنا وهنشيله فورًا.",
  "Ministry website": "موقع الوزارة",
