const cache: Partial<Record<Language, Record<string, string>>> = { en: {}, ar: { ...arabic, ...arabicExtra, ...playAr } }

const loaders: Partial<Record<Language, () => Promise<Record<string, string>>>> = {
  fr: () => import('./locales/fr').then((module) => ({ ...module.french, ...playLocales.fr })),
  es: () => import('./locales/es').then((module) => ({ ...module.spanish, ...playLocales.es })),
  de: () => import('./locales/de').then((module) => ({ ...module.german, ...playLocales.de })),
  tr: () => import('./locales/tr').then((module) => ({ ...module.turkish, ...playLocales.tr })),
  id: () => import('./locales/id').then((module) => ({ ...module.indonesian, ...playLocales.id })),
}

export async function loadLanguage(language: Language): Promise<void> {
  if (cache[language]) return
  const loader = loaders[language]
  if (!loader) return
  try {
    cache[language] = await loader()
  } catch {
    cache[language] = {}
  }
}

export function isLanguageLoaded(language: Language): boolean {
  return Boolean(cache[language])
}

let active: Language = 'en'

export function setI18nLanguage(language: Language | undefined) {
  active = language && cache[language] ? language : 'en'
  if (typeof document !== 'undefined') {
    document.documentElement.lang = active
    document.documentElement.dir = active === 'ar' ? 'rtl' : 'ltr'
    document.title =
      active === 'ar'
        ? 'Jessica — عالم تعلّم ذكي'
        : active === 'fr'
          ? "Jessica — Apprends avec l'IA"
          : active === 'es'
            ? 'Jessica — Aprende con IA'
            : active === 'de'
              ? 'Jessica — Lerne mit KI'
              : active === 'tr'
                ? 'Jessica — Yapay zekâ ile öğren'
                : active === 'id'
                  ? 'Jessica — Belajar dengan AI'
                  : 'Jessica — AI Learning Universe'
  }
}

/** Locale used for dates and numbers. */
export function dateLocale() {
  if (active === 'ar') return 'ar-EG'
  if (active === 'fr') return 'fr-FR'
  if (active === 'es') return 'es-ES'
  if (active === 'de') return 'de-DE'
  if (active === 'tr') return 'tr-TR'
  if (active === 'id') return 'id-ID'
  return 'en-GB'
}

export function getLanguage(): Language {
  return active
}

const AR_DIGITS = '٠١٢٣٤٥٦٧٨٩'

/** Numbers read better in Arabic-Indic digits when the UI is Arabic. */
export function num(value: number | string): string {
  const text = String(value)
  if (getLanguage() !== 'ar') return text
  return text.replace(/[0-9]/g, (digit) => AR_DIGITS[Number(digit)])
}

function fill(text: string, vars?: Record<string, string | number>) {
  if (!vars) return text
  return text.replace(/\{(\w+)\}/g, (_, key: string) => String(vars[key] ?? `{${key}}`))
}

/**
 * Translate an English UI string. Preserves the surrounding whitespace that
 * JSX gives us, so wrapping text nodes does not glue words together.
 */
export function tr(text: string, vars?: Record<string, string | number>) {
  if (typeof text !== 'string') return text == null ? '' : String(text)
  if (active === 'en') return fill(text, vars)
  const lead = text.match(/^\s*/)?.[0] ?? ''
  const trail = text.match(/\s*$/)?.[0] ?? ''
  const key = text.replace(/\s+/g, ' ').trim()
  const translated = (cache[active] || {})[key] ?? key
  return lead + fill(translated, vars) + trail
}

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const language = useApp((s) => s.settings.language)
  const [, force] = useState(0)
  const [ready, setReady] = useState(() => isLanguageLoaded(language))

  useEffect(() => {
    let cancelled = false
    if (isLanguageLoaded(language)) {
      setI18nLanguage(language)
      setReady(true)
      force((value) => value + 1)
      return
    }
    setReady(false)
    loadLanguage(language).then(() => {
      if (cancelled) return
      setI18nLanguage(language)
      setReady(true)
      force((value) => value + 1)
    })
    return () => {
      cancelled = true
    }
  }, [language])

  setI18nLanguage(language)
  if (!ready) {
    return (
      <div className="grid min-h-dvh place-items-center bg-ink-950 text-sm font-bold text-muted">
        Loading…
      </div>
    )
  }
  return <Fragment key={language}>{children}</Fragment>
}
